    mp_help_html: "Ongeza maeneo yanayokuhusu — kazini kwako, shule ya mtoto wako, eneo unalolipenda. Chagua safu, kisha <strong>tafuta</strong> (mkoa, wilaya, kata, kijiji, au huduma kama shule, hospitali au soko), gusa <strong>ramani</strong>, au tumia <strong>GPS</strong>. Kama mahali hasa hapapatikani, tutakutajia eneo lililo karibu. Kisha tunapanga nyumba zinazolingana na maisha yako — weka muda wa juu wa safari ili kuficha zilizo mbali sana.",
